<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal employee-edit-modal" role="dialog" aria-modal="true" aria-labelledby="advance-edit-title"><div class="customer-modal-header"><div><span class="modal-eyebrow">Staff advance</span><h2 id="advance-edit-title">Edit Employee Advance</h2><span class="modal-code"><?= e($advanceEdit['employee_code']) ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=employees-advances" aria-label="Close">&times;</a></div><div class="customer-modal-body"><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="index.php?page=admin&amp;section=employees-advances"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="advance_id" value="<?= (int)$advanceEdit['id'] ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Employee *</label><select class="form-select" name="employee_id" required><?php foreach($options as $option): ?><option value="<?= (int)$option['id'] ?>" <?= (int)$option['id']===(int)$advanceEdit['employee_id']?'selected':'' ?>><?= e($option['name'].' ('.$option['employee_code'].')') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Advance Date *</label><input class="form-control" type="date" name="advance_date" value="<?= e($advanceEdit['advance_date']) ?>" required></div><div class="col-md-6"><label class="form-label">Amount *</label><input class="form-control" type="number" name="amount" min=".01" step=".01" value="<?= e((string)$advanceEdit['amount']) ?>" required></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><option value="unsettled" <?= $advanceEdit['status']==='unsettled'?'selected':'' ?>>Unsettled</option><option value="settled" <?= $advanceEdit['status']==='settled'?'selected':'' ?>>Settled</option></select></div><div class="col-12"><label class="form-label">Reason</label><input class="form-control" name="reason" value="<?= e($advanceEdit['reason']??'') ?>"></div></div><div class="customer-modal-footer px-0 pb-0"><a class="btn btn-light" href="index.php?page=admin&amp;section=employees-advances">Cancel</a><button class="btn btn-primary" type="submit">Update Advance</button></div></form></div></section></div>
